function calculatePointInfo(entity, divideCount, divideLength) {
  const pointInfoList = [];
  if (!divideCount && !divideLength) {
    return pointInfoList;
  }
  if (entity instanceof McDbLine) {
    const line2 = entity.toMcGe();
    const length = line2.length();
    const step = divideCount ? length / divideCount : divideLength ?? 1;
    for (let len = step; len < length; len += step) {
      const pa = line2.getPaFromDist(len);
      const point = new McGePoint2d();
      line2.getPtFromParam(pa, point);
      const dir = new McGeVector2();
      line2.getTangent(pa, dir);
      pointInfoList.push({
        point: new McGeVector3(point.x, point.y, 0),
        angle: new McGeVector2(dir.x, dir.y).angle()
      });
    }
  } else if (entity instanceof McDbPolyLine || entity instanceof McDbSpline || entity instanceof McDbEllipse) {
    const line2 = entity.toMcGe();
    const length = line2.length();
    const step = divideCount ? length / divideCount : divideLength ?? 1;
    for (let len = step; len < length; len += step) {
      const pa = line2.getPaFromDist(len);
      const point = new McGePoint2d();
      line2.getPtFromParam(pa, point);
      const dir = new McGeVector2();
      line2.getTangent(pa, dir);
      pointInfoList.push({
        point: new McGeVector3(point.x, point.y, 0),
        angle: new McGeVector2(dir.x, dir.y).angle()
      });
    }
  } else if (entity instanceof McDbCircle) {
    const circle = entity.toMcGe();
    const { radius } = circle;
    const length = 2 * Math.PI * radius;
    const step = divideCount ? length / divideCount : divideLength ?? 1;
    for (let len = 0; len < length; len += step) {
      const pa = circle.getPaFromDist(len);
      const point = new McGePoint2d();
      circle.getPtFromParam(pa, point);
      pointInfoList.push({
        point: new McGeVector3(point.x, point.y, 0),
        angle: len / radius
      });
    }
  } else if (entity instanceof McDbArc) {
    const arc = entity.toMcGe();
    const length = arc.length();
    const step = divideCount ? length / divideCount : divideLength ?? 1;
    for (let len = step; len < length; len += step) {
      const pa = arc.getPaFromDist(len);
      const point = new McGePoint2d();
      arc.getPtFromParam(pa, point);
      const dir = new McGeVector2();
      arc.getTangent(pa, dir);
      pointInfoList.push({
        point: new McGeVector3(point.x, point.y, 0),
        angle: new McGeVector2(dir.x, dir.y).angle()
      });
    }
  }
  return pointInfoList;
}
async function quarantineObject(core2) {
  const rootCore = core2 ?? getCurCoreInstance();
  if (!rootCore) {
    return;
  }
  const db = rootCore.getDatabase();
  if (!db) {
    return;
  }
  const objectList = [];
  const selectedEntities = rootCore.getSelectedEntities();
  if (!selectedEntities || selectedEntities.size === 0) {
    const prGetEntities = new McPrGetEntities(rootCore);
    prGetEntities.setSelectMode(McSelectEntityMode.eRect);
    prGetEntities.setPickMode(McPickEntityMode.eMultiple);
    while (true) {
      prGetEntities.setMessage("请选择要隔离的对象");
      const mcPrResultStatus = await prGetEntities.run();
      if (mcPrResultStatus.status == McPrErrorStatus.eOK) {
        if (mcPrResultStatus.entities && mcPrResultStatus.entities.length > 0)
          objectList.push(...mcPrResultStatus.entities);
        break;
      } else if (mcPrResultStatus.status == McPrErrorStatus.eKeyword) {
        if (mcPrResultStatus.key == "Enter" || mcPrResultStatus.key == "确定") {
          break;
        } else if (mcPrResultStatus.key == "Escape" || mcPrResultStatus.key == "取消") {
          return;
        }
      } else if (mcPrResultStatus.status == McPrErrorStatus.eCancel) {
        return;
      }
    }
  } else {
    objectList.push(...selectedEntities.values().toArray());
  }
  for (const [id2, ent] of db.getEntityTable().getEntities()) {
    if (isSelect(id2))
      continue;
    const layer = ent.getLayer();
    if (!layer || layer && (layer.getIsOff() || layer.getIsFrozen()))
      continue;
    ent.setVisibility(false);
    ent.update();
  }
  function isSelect(id2) {
    return objectList.some((obj) => {
      if (obj instanceof McDbEntity)
        return obj._objectId === id2;
      else if (obj instanceof McDbGroup)
        return obj.children.includes(id2);
      return false;
    });
  }
}
