  const group = db.getGroupTable().getById(groupID);
  if (!group) {
    return;
  }
  const entities = [];
  const mcPrGetEntities = new McPrGetEntities(rootCore);
  mcPrGetEntities.setMessage("选择对象：");
  mcPrGetEntities.setSelectMode(McSelectEntityMode.eRect);
