    const dir2 = new McGeVector3().subVectors(point, center);
    const tempCube = new McDbCube(tempSize);
    const angle2 = dir2.toMcGeVector2().angle();
    tempCube.setRotation(new McGeVector3(0, 0, angle2));
    tempCube.setPosition(center.clone().add(
      new McGeVector3(tempSize / 2, tempSize / 2, 0).applyAxisAngle(new McGeVector3(0, 0, 1), angle2)
    ));
