  let dir = new McGeVector3().subVectors(secondPoint2, center);
  if (dir.length() == 0) {
    dir = new McGeVector3(1, 0, center.z);
  }
  const angle = dir.toMcGeVector2().angle();
  cube.setRotation(new McGeVector3(0, 0, angle));
  cube.setPosition(center.clone().add(
    new McGeVector3(size / 2, size / 2, 0).applyAxisAngle(new McGeVector3(0, 0, 1), angle)
  ));
  cube.useCurDrawProperties();
