    mcPrGetEntities.setMessage(msg);
    mcPrGetEntities.setSelectMode(McSelectEntityMode.eRect);
    mcPrGetEntities.setPickMode(McPickEntityMode.eMultiple);
    mcPrGetEntities.setCursorType(McPrCurType.eRect);
